add_action( 'woocommerce_after_checkout_validation', 'perfectpixel_block_blacklisted_emails', 10, 2 );

function perfectpixel_block_blacklisted_emails( $data, $errors ) {
	$email = strtolower( trim( (string) ( $data['billing_email'] ?? '' ) ) );
	if ( '' === $email ) {
		return;
	}
	$list = array_filter( array_map( 'trim', explode( ',', strtolower( '{{blocked_emails}}' ) ) ) );

	foreach ( $list as $entry ) {
		$is_domain = 0 === strpos( $entry, '@' );
		if ( ( $is_domain && substr( $email, -strlen( $entry ) ) === $entry ) || ( ! $is_domain && $email === $entry ) ) {
			$errors->add( 'perfectpixel_blocked_email', esc_html( '{{blocked_message}}' ) );
			return;
		}
	}
}
